def solve(rows):
  """Calculates the total cost of rows according to the given rules."""
  audit_positions = [(i, row) for i, row in enumerate(rows)]
  filtered_positions = [(i, row) for i, row in audit_positions if i % 5 != 3 or i == len(audit_positions) - 1]

  if not filtered_positions:
    return 0

  last_index = filtered_positions[-1][0]
  rotated_rows = []
  for i in range(len(filtered_positions)):
    if i < last_index: 
      rotated_rows.append(filtered_positions[i][1])
    else: 
      rotated_rows.append(filtered_positions[i][1])

  if not rotated_rows: 
    return 0

  total_cost = 0
  for row in rotated_rows:
    if row >= 0:
      if row <= 15:
        cost = row * 8
      else:
        cost = 15 * 8 + (row - 15) * 7

      if cost <= 133:
        total_cost += cost
      else:
        total_cost += 133

  return total_cost

